import React, { useState, useEffect, useRef } from 'react';
import { View, Text, TextInput, Button, FlatList, StyleSheet } from 'react-native';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';

export default function ChatRoom({ route, navigation }) {
    const { roomId, roomName } = route.params;
    const [messages, setMessages] = useState([]);
    const [messageContent, setMessageContent] = useState('');
    const [userId, setUserId] = useState(null);
    const stompClient = useRef(null);

    useEffect(() => {
        const fetchUserId = async () => {
            try {
                const storedUserId = await AsyncStorage.getItem('userId');
                if (storedUserId) {
                    setUserId(storedUserId);
                    connectToChatRoom(storedUserId);
                    fetchMessages();
                }
            } catch (error) {
                console.error('Failed to load user ID:', error);
            }
        };

        fetchUserId();

        return () => {
            if (stompClient.current) {
                stompClient.current.deactivate();
            }
        };
    }, []);

    const fetchMessages = async () => {
        try {
            const response = await axios.get(`http://172.30.1.52:8081/api/chatrooms/${roomId}/messages`);
            const messagesData = Array.isArray(response.data) ? response.data : [];
            setMessages(messagesData);
        } catch (error) {
            console.error('Failed to fetch messages:', error);
        }
    };

    const connectToChatRoom = (userId) => {
        const socket = new SockJS('http://172.30.1.52:8081/ws');
        stompClient.current = new Client({
            webSocketFactory: () => socket,
            onConnect: () => {
                console.log('Connected to chat room');
                stompClient.current.subscribe(`/topic/public`, (message) => {
                    const receivedMessage = JSON.parse(message.body);
                    if (receivedMessage.roomId === roomId) {
                        setMessages((prevMessages) => [...prevMessages, receivedMessage]);
                    }
                });
            },
            onStompError: (frame) => {
                console.error('Broker reported error: ' + frame.headers['message']);
                console.error('Additional details: ' + frame.body);
            },
        });

        stompClient.current.activate();
    };

    const sendMessage = async () => {
        if (messageContent.trim() && stompClient.current && userId) {
            const message = {
                sender: userId,
                content: messageContent,
                roomId: roomId,
            };
            stompClient.current.publish({
                destination: '/app/chat.sendMessage',
                body: JSON.stringify(message),
            });

            try {
                await axios.post(`http://172.30.1.52:8081/api/chatrooms/${roomId}/messages`, message);
                setMessages((prevMessages) => [...prevMessages, message]);
                setMessageContent('');
            } catch (error) {
                console.error('Failed to send message:', error);
            }
        }
    };

    const renderItem = ({ item }) => (
        <View style={[styles.message, item.sender === userId ? styles.sentMessage : styles.receivedMessage]}>
            <Text style={styles.sender}>{item.sender}:</Text>
            <Text>{item.content}</Text>
        </View>
    );

    return (
        <View style={styles.container}>
            <Text style={styles.roomName}>{roomName}</Text>
            <FlatList data={messages} renderItem={renderItem} keyExtractor={(item, index) => index.toString()} />
            <View style={styles.inputContainer}>
                <TextInput
                    style={styles.input}
                    value={messageContent}
                    onChangeText={setMessageContent}
                    placeholder="Type a message..."
                />
                <Button title="Send" onPress={sendMessage} />
            </View>
        </View>
    );
}

const styles = StyleSheet.create({
    container: {
        flex: 1,
        justifyContent: 'space-between',
    },
    roomName: {
        fontSize: 24,
        fontWeight: 'bold',
        padding: 16,
        backgroundColor: '#f4f4f4',
        borderBottomWidth: 1,
        borderBottomColor: '#ccc',
    },
    message: {
        flexDirection: 'row',
        padding: 10,
        borderRadius: 10,
        margin: 5,
        maxWidth: '80%',
    },
    sentMessage: {
        alignSelf: 'flex-end',
        backgroundColor: '#dcf8c6',
    },
    receivedMessage: {
        alignSelf: 'flex-start',
        backgroundColor: '#f1f1f1',
    },
    sender: {
        fontWeight: 'bold',
        marginRight: 5,
    },
    inputContainer: {
        flexDirection: 'row',
        padding: 10,
        borderTopWidth: 1,
        borderTopColor: '#ccc',
    },
    input: {
        flex: 1,
        borderWidth: 1,
        borderColor: '#ccc',
        borderRadius: 5,
        paddingHorizontal: 8,
        marginRight: 10,
    },
});
